WITH base AS (SELECT *, UPPER(txn_type) AS txn_type_upper, COALESCE(merchant, 'DIRECT') AS merchant_filled FROM transactions WHERE merchant IS NOT NULL AND amount BETWEEN 1200 AND 1900), filtered AS (SELECT *, LENGTH(txn_type) AS txn_type_length, CASE WHEN amount >= 4200 THEN 'High' WHEN amount >= 1200 THEN 'Medium' ELSE 'Low' END AS amount_level FROM base WHERE txn_time >= TO_TIMESTAMP('2023-08-06 20:00:00')), enriched AS (SELECT id, txn_type, amount, merchant, is_flagged, txn_type_upper, merchant_filled, txn_type_length, COUNT(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_amount, MIN(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, SUM(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_amount FROM filtered), valid AS (SELECT *, UPPER(merchant) AS merchant_upper, COALESCE(merchant, 'OTHER') AS merchant_filled_2 FROM enriched WHERE running_min_amount > 3100), cleaned AS (SELECT id, txn_type, amount, merchant, is_flagged, merchant_filled, running_count_amount, running_min_amount, running_sum_amount, merchant_upper, merchant_filled_2, CASE WHEN running_count_amount >= 18 THEN 'High' WHEN running_count_amount >= 7 THEN 'Medium' ELSE 'Low' END AS running_count_amount_level, LENGTH(merchant) AS merchant_length FROM valid WHERE merchant IS NOT NULL), valid_transactions AS (SELECT *, LENGTH(merchant) AS merchant_length_2 FROM cleaned WHERE merchant_length = 49) SELECT id, amount, merchant, is_flagged, running_count_amount, running_min_amount, running_sum_amount, merchant_upper, merchant_filled_2 FROM valid_transactions
